const { execSync } = require('child_process');
const projectName = $('imposta-progetto').item.json.projectName;
const pdfPath = $('imposta-progetto').item.json.pdfPath;
const out = execSync(`/bin/pdfinfo "${pdfPath}"`).toString();
const match = out.match(/Pages:\s+(\d+)/);
const nPages = match ? parseInt(match[1], 10) : 0;
const pages = [];
for (let p = 1; p <= nPages; p++) {
  pages.push({ json: { projectName, pdfPath, page: p } });
}
return pages;

const fs = require('fs');
const item = $input.item;
const projectName = item.json.projectName;
const page = item.json.page;
const filePath = `/shared/projects/${projectName}/markdown/page_${page}.md`;
const exists = fs.existsSync(filePath);
item.json.paginaGiaFatta = exists;
if (exists) {
  item.json.fileName = `page_${page}.md`;
  item.json.filePath = filePath;
  item.json.markdown = fs.readFileSync(filePath, 'utf8');
}
return item;

const items = $input.all();
let projectName = items[0]?.json?.projectName || '';
if (!projectName) { try { projectName = $('imposta-progetto').first().json.projectName; } catch(e) {} }

const results = [];
for (const item of items) {
  const pageNum = item.json.page;
  const text = (item.json.markdown || '').trim();
  results.push({
    json: {
      fileName: item.json.fileName || `page_${pageNum}.md`,
      projectName,
      page: pageNum,
      finalContent: `# ${projectName} - Pagina ${pageNum}\n\n${text}`
    }
  });
}
return results;

const fs = require('fs');
const items = $input.all();
let projectName = items[0]?.json?.projectName || '';
if (!projectName) { try { projectName = $('imposta-progetto').first().json.projectName; } catch(e) {} }

const fixesPath = `/shared/projects/${projectName}/manual_fixes.json`;

let fixes = [];
if (fs.existsSync(fixesPath)) {
  try {
    fixes = JSON.parse(fs.readFileSync(fixesPath, 'utf8'));
  } catch (e) {
    throw new Error(`manual_fixes.json non e' JSON valido per il progetto '${projectName}': ${e.message}`);
  }
}

if (fixes.length === 0) {
  return items;
}

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function applyFix(text, fix) {
  const pattern = fix.regex
    ? new RegExp(fix.find, fix.flags || 'g')
    : new RegExp(escapeRegExp(fix.find), 'g');
  return text.replace(pattern, fix.replace);
}

for (const item of items) {
  const pageNum = item.json.page;
  let text = item.json.finalContent || '';
  for (const fix of fixes) {
    if (fix.page != null && fix.page !== pageNum) continue;
    text = applyFix(text, fix);
  }
  item.json.finalContent = text;
}

return items;

const items = $input.all();
let projectName = items[0]?.json?.projectName || '';
if (!projectName) {
  try { projectName = $('imposta-progetto').first().json.projectName; } catch(e) {}
}
const finalContent = items.map(i => i.json.finalContent);
