const fs = require('fs');
const items = $input.all();
let projectName = items[0]?.json?.projectName || '';
if (!projectName) { try { projectName = $('imposta-progetto').first().json.projectName; } catch(e) {} }

const finalContents = items[0].json.finalContent;
const joined = Array.isArray(finalContents)
  ? finalContents
      .map(c => String(c).replace(/^# [^\n]+ - Pagina \d+\s*\n\n?/, ''))
      .join('\n\n---\n\n')
  : String(finalContents || '').replace(/^# [^\n]+ - Pagina \d+\s*\n\n?/, '');

const filePath = `/shared/projects/${projectName}/${projectName}.md`;
fs.writeFileSync(filePath, joined, 'utf8');

return [{ json: { saved: filePath, projectName, bytes: Buffer.byteLength(joined, 'utf8') } }];

const fs = require('fs');
const items = $input.all();
const projectName = items[0]?.json?.projectName || $('imposta-progetto').first().json.projectName;

const capitoliDir = `/shared/projects/${projectName}/capitoli`;

if (fs.existsSync(capitoliDir)) {
  for (const f of fs.readdirSync(capitoliDir)) {
    fs.unlinkSync(`${capitoliDir}/${f}`);
  }
}
fs.mkdirSync(capitoliDir, { recursive: true });

const texts = items.map(item => {
  let content = item.json.finalContent || '';
  content = content.replace(/^# .+? - Pagina \d+\s*\n/, '');
  return content.trim();
});

let fullText = texts.join('\n\n<!-- pb -->\n\n');

fullText = fullText.replace(/(\w)-\n\n<!-- pb -->\n\n(\w)/g, '$1$2');
fullText = fullText.replace(/([^.!?:;»\")\]\n])\n\n<!-- pb -->\n\n([a-z\u00e0-\u00fc])/g, '$1 $2');
fullText = fullText.replace(/\n*<!-- pb -->\n*/g, '\n\n');
fullText = fullText.replace(/\n{3,}/g, '\n\n');

const parts = fullText.split(/(?=^## )/m).filter(p => p.trim());

if (parts.length === 0) {
  const filename = `${capitoliDir}/01-completo.md`;
  fs.writeFileSync(filename, fullText, 'utf8');
  return [{ json: { salvati: 1, files: [filename], projectName } }];
}

const savedFiles = [];
for (let i = 0; i < parts.length; i++) {
  const content = parts[i].trim();
  const firstLine = content.split('\n')[0].trim();
  let title = firstLine.replace(/^#+\s*/, '').trim();
  if (/^!\[.*\]\(.*\)/.test(firstLine) || !title) {
    title = 'COPERTINA';
  }
  const slug = title
    .toLowerCase()
    .replace(/[\u00e0\u00e1\u00e2\u00e4]/g, 'a').replace(/[\u00e8\u00e9\u00ea\u00eb]/g, 'e')
    .replace(/[\u00ec\u00ed\u00ee\u00ef]/g, 'i').replace(/[\u00f2\u00f3\u00f4\u00f6]/g, 'o').replace(/[\u00f9\u00fa\u00fb\u00fc]/g, 'u')
    .replace(/[^a-z0-9.]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
  const filename = `${capitoliDir}/${String(i + 1).padStart(2, '0')}-${slug}.md`;
  fs.writeFileSync(filename, content, 'utf8');
  savedFiles.push({ index: i + 1, title, filename });
}

return [{ json: { salvati: savedFiles.length, files: savedFiles, projectName } }];

const { execSync } = require('child_process');
const item = $input.item;
const page = item.json.page;

// Riavvio periodico del motore VLM (llama-server, PaddleOCR-VL) ogni 15
// pagine: leak di memoria per-richiesta, stesso tipo di problema gia'
// visto e risolto per Surya (vedi dnb_surya_layout_integration) - il fix
// sulla dimensione iniziale (--parallel 1 --ctx-size 16384) abbassa il
// punto di partenza ma non ferma la crescita nel tempo. Verificato:
// riavviato pulito a ~719MB, tornato a 7.3GB dopo ~90 pagine, causa di
// swap thrashing sull'host (2026-08-04). Fire-and-forget (timeout client
// breve): il riavvio prosegue lato server anche se n8n non aspetta.
if (page % 15 === 0) {
  try {
    execSync('curl -s -m 3 -X POST http://PADDLEOCR_GATEWAY_HOST:8091/restart_vlm');
  } catch (e) {
    // Se il riavvio fallisce (rete, timeout) si prosegue comunque - una
    // singola pagina lenta e' preferibile a bloccare l'intero libro.
  }
}

return item;
